@push('scripts')<script>
const products=@json($products->map(fn($p)=>['id'=>$p->id,'name'=>$p->name,'price'=>(float)$p->purchase_price])->values());
const existing=@json(old('items',$purchase?->items?->map(fn($i)=>['product_id'=>$i->product_id,'quantity'=>(float)$i->quantity,'unit_cost'=>(float)$i->unit_cost,'discount'=>(float)$i->discount,'tax'=>(float)$i->tax])->values()->all()??[]));let idx=0;
function row(data={}){const opts=products.map(p=>`<option value="${p.id}" ${String(data.product_id)==String(p.id)?'selected':''}>${p.name}</option>`).join('');const tr=document.createElement('tr');tr.innerHTML=`<td><select class="form-select product" name="items[${idx}][product_id]" required><option value="">Select</option>${opts}</select></td><td><input class="form-control" type="number" step="0.0001" min="0.0001" name="items[${idx}][quantity]" value="${data.quantity??1}" required></td><td><input class="form-control cost" type="number" step="0.0001" min="0" name="items[${idx}][unit_cost]" value="${data.unit_cost??0}" required></td><td><input class="form-control" type="number" step="0.01" min="0" name="items[${idx}][discount]" value="${data.discount??0}"></td><td><input class="form-control" type="number" step="0.01" min="0" name="items[${idx}][tax]" value="${data.tax??0}"></td><td><button type="button" class="btn btn-sm btn-outline-danger remove">×</button></td>`;tr.querySelector('.product').addEventListener('change',e=>{const p=products.find(x=>String(x.id)===e.target.value);if(p)tr.querySelector('.cost').value=p.price});tr.querySelector('.remove').onclick=()=>tr.remove();document.querySelector('#items-table tbody').appendChild(tr);idx++;}
document.getElementById('add-item').onclick=()=>row();(existing.length?existing:[{}]).forEach(row);
</script>@endpush
